  // ---------- ROLL LAB ----------
  // Illustrative model: constant rolling-resistance coefficient + quadratic air drag (rho 1.2), constant braking deceleration.
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("rl-speed")) return;
    const g = 9.81, rho = 1.2;
    let crr = 0.01, cda = 0.45;
    function fmt(x, d) { return x.toFixed(d); }
    function seg(id, attr, set) {
      const box = $(id);
      box.querySelectorAll("button").forEach(b => b.addEventListener("click", () => {
        box.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
        set(+b.getAttribute(attr)); update();
      }));
    }
    function update() {
      const kmh = +$("rl-speed").value, m = +$("rl-mass").value, dec = +$("rl-dec").value, rt = +$("rl-rt").value;
      $("rl-speed-o").textContent = kmh + " km/h";
      $("rl-mass-o").textContent = m + " kg";
      $("rl-dec-o").textContent = fmt(dec, 1) + " m/s²";
      $("rl-rt-o").textContent = fmt(rt, 1) + " s";
      const v = kmh / 3.6, W = m * g;
      const Froll = crr * W, k = 0.5 * rho * cda, Fdrag = k * v * v;
      const P = (Froll + Fdrag) * v;
      const coast = (m / (2 * k)) * Math.log(1 + k * v * v / Froll);
      const brake = v * v / (2 * dec), react = v * rt;
      $("rl-roll").textContent = fmt(Froll, 1) + " N";
      $("rl-drag").textContent = fmt(Fdrag, 1) + " N";
      $("rl-power").textContent = Math.round(P) + " W";
      $("rl-coast").textContent = Math.round(coast) + " m";
      $("rl-brake").textContent = fmt(brake, 1) + " m";
      $("rl-total").textContent = fmt(brake + react, 1) + " m";
      $("rl-react").textContent = fmt(react, 1) + " m";
      $("rl-drop").textContent = fmt(v * v / (2 * g), 2) + " m";
      $("rl-rpm").textContent = Math.round(v / (Math.PI * 0.08) * 60) + " rpm";
      $("rl-bar").style.width = Math.min(100, (brake + react) / 40 * 100) + "%";
    }
    seg("rl-surface", "data-crr", x => { crr = x; });
    seg("rl-posture", "data-cda", x => { cda = x; });
    ["rl-speed", "rl-mass", "rl-dec", "rl-rt"].forEach(id => $(id).addEventListener("input", update));
    update();
  })();

